package com.strikermall;
import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.time.*;
import java.math.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.*;

/** Striker Mall: Java 17+ HTTP API + embedded HSQLDB. No Python needed. */
public final class Server {
 static final Map<String,Integer> sessions=new ConcurrentHashMap<>();static final SecureRandom random=new SecureRandom();static final Object dbLock=new Object();
 static final String[] orderStatuses={"PLACED","PACKING","SHIPPED","DELIVERED"};
 static Map<String,Object> map(Object...kv){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<kv.length;i+=2)m.put((String)kv[i],kv[i+1]);return m;}
 static String val(Map<String,Object> m,String key){return Db.str(m.get(key));}
 static String req(Map<String,Object> m,String key,int max){String s=val(m,key).trim();if(s.isEmpty()||s.length()>max)throw new Bad(key.replace('_',' ')+" is required (maximum "+max+" characters).");return s;}
 static int integer(Object v,int low,int high){try{int x=Integer.parseInt(Db.str(v));if(x<low||x>high)throw new NumberFormatException();return x;}catch(Exception e){throw new Bad("Enter a whole number between "+low+" and "+high+".");}}
 static BigDecimal money(Object v){try{BigDecimal d=new BigDecimal(Db.str(v)).setScale(2,RoundingMode.HALF_UP);if(d.signum()<0||d.compareTo(new BigDecimal("100000000"))>0)throw new Exception();return d;}catch(Exception e){throw new Bad("Enter a valid non-negative price.");}}
 static boolean active(Object o){return o==null||o.equals(true)||o.equals(1)||o.equals("true");}
 static boolean contains(String[] a,String v){return Arrays.asList(a).contains(v);}
 static class Bad extends RuntimeException{int code=400;Bad(String message){super(message);}Bad(String message,int code){super(message);this.code=code;}}
 static Map<String,Object> account(Connection c,int id)throws Exception{return Db.row(c,"SELECT id,full_name,phone,email,username,role FROM users WHERE id=?",id);}
 static List<Map<String,Object>> products(Connection c)throws Exception{List<Map<String,Object>> rows=Db.rows(c,"SELECT p.*,s.name AS shop_name,s.category AS category FROM products p JOIN shops s ON s.id=p.shop_id WHERE p.active=1 AND s.active=1 ORDER BY p.id");for(Map<String,Object> p:rows){Map<String,String> specs=new LinkedHashMap<>();for(Map<String,Object> spec:Db.rows(c,"SELECT spec_key,spec_value FROM product_specs WHERE product_id=?",p.get("id")))specs.put(Db.str(spec.get("spec_key")),Db.str(spec.get("spec_value")));p.put("specs",specs);}return rows;}
 static Map<String,Object> settings(Connection c)throws Exception{Map<String,Object> out=new LinkedHashMap<>();for(Map<String,Object> r:Db.rows(c,"SELECT key,value FROM settings"))out.put(Db.str(r.get("key")),r.get("value"));return out;}
 static List<Map<String,Object>> orders(Connection c,Map<String,Object> user)throws Exception{List<Map<String,Object>> rows="ADMIN".equals(user.get("role"))?Db.rows(c,"SELECT o.*,u.full_name AS customer_name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC"):Db.rows(c,"SELECT o.*,u.full_name AS customer_name FROM orders o JOIN users u ON u.id=o.user_id WHERE o.user_id=? ORDER BY o.id DESC",user.get("id"));for(Map<String,Object> r:rows)r.put("items",Db.rows(c,"SELECT * FROM order_items WHERE order_id=?",r.get("id")));return rows;}
 static Object handle(Connection c,String method,String path,Map<String,Object> b,Map<String,Object> user)throws Exception{
  if(path.equals("/api/config")&&method.equals("GET"))return map("settings",settings(c),"shops",Db.rows(c,"SELECT * FROM shops WHERE active=1 ORDER BY id"),"product_count",Db.number(c,"SELECT COUNT(*) FROM products WHERE active=1"));
  if(path.equals("/api/me")&&method.equals("GET"))return map("user",user);
  if(path.equals("/api/login")&&method.equals("POST")){String name=req(b,"username",40),pass=req(b,"password",128);Map<String,Object> a=Db.row(c,"SELECT * FROM users WHERE username=?",name);if(a==null||!MessageDigest.isEqual(Db.hash(pass,Db.str(a.get("password_salt"))).getBytes(StandardCharsets.UTF_8),Db.str(a.get("password_hash")).getBytes(StandardCharsets.UTF_8)))throw new Bad("Invalid username or password.",401);return map("login_user_id",a.get("id"),"user",account(c,((Number)a.get("id")).intValue()));}
  if(path.equals("/api/register")&&method.equals("POST")){String name=req(b,"full_name",80),username=req(b,"username",40),password=req(b,"password",128),phone=req(b,"phone",20);String email=val(b,"email").trim();if(email.length()>120)throw new Bad("Email too long.");if(password.length()<8)throw new Bad("Password needs at least 8 characters.");if(!username.matches("[a-zA-Z0-9_.@+-]{3,40}"))throw new Bad("Username must be 3–40 letters, digits or . _ @ + - characters.");if(Db.row(c,"SELECT id FROM users WHERE username=?",username)!=null)throw new Bad("That username is already taken.");String salt=Db.salt();int id=Db.insert(c,"INSERT INTO users(full_name,phone,username,email,password_salt,password_hash,role,created_at) VALUES(?,?,?,?,?,?,?,?)",name,phone,username,email,salt,Db.hash(password,salt),"CUSTOMER",Db.now());return map("login_user_id",id,"user",account(c,id));}
  if(path.equals("/api/logout")&&method.equals("POST"))return map("logout",true);
  if(user==null)throw new Bad("Please sign in first.",401);
  if(path.equals("/api/products")&&method.equals("GET"))return map("products",products(c));
  if(path.equals("/api/checkout")&&method.equals("POST")){
   Object input=b.get("items");if(!(input instanceof List<?>)||((List<?>)input).isEmpty()||((List<?>)input).size()>100)throw new Bad("Add products to your bag first.");String name=req(b,"delivery_name",80),phone=req(b,"delivery_phone",20),address=req(b,"delivery_address",400);if(!phone.matches("[0-9+()\\- ]{7,20}"))throw new Bad("Enter a valid delivery phone number.");
   Map<Integer,Integer> quantities=new LinkedHashMap<>();for(Object item:(List<?>)input){if(!(item instanceof Map<?,?>))throw new Bad("Invalid shopping bag.");Map<?,?> i=(Map<?,?>)item;int pid=integer(i.get("product_id"),1,Integer.MAX_VALUE),qty=integer(i.get("qty"),1,100);quantities.merge(pid,qty,Integer::sum);if(quantities.get(pid)>100)throw new Bad("Too many items.");}
   BigDecimal subtotal=BigDecimal.ZERO,tax=BigDecimal.ZERO;List<Object[]> lines=new ArrayList<>();
   for(var entry:quantities.entrySet()){int pid=entry.getKey(),qty=entry.getValue();Map<String,Object> p=Db.row(c,"SELECT p.*,s.category FROM products p JOIN shops s ON p.shop_id=s.id WHERE p.id=? AND p.active=1 AND s.active=1",pid);if(p==null)throw new Bad("Product #"+pid+" is no longer available.");int stock=((Number)p.get("stock")).intValue();if(stock<qty)throw new Bad("Only "+stock+" left of "+p.get("name")+". Please update your bag.");BigDecimal unit=money(p.get("price"));BigDecimal rate=contains(new String[]{"TECH","SUPPLEMENT"},Db.str(p.get("category")))?new BigDecimal("0.18"):new BigDecimal("0.05");subtotal=subtotal.add(unit.multiply(BigDecimal.valueOf(qty)));tax=tax.add(unit.multiply(BigDecimal.valueOf(qty)).multiply(rate).setScale(2,RoundingMode.HALF_UP));lines.add(new Object[]{pid,p.get("name"),qty,unit,rate});}
   int id=Db.insert(c,"INSERT INTO orders(user_id,created_at,subtotal,gst,total,status,delivery_name,delivery_phone,delivery_address,notes) VALUES(?,?,?,?,?,?,?,?,?,?)",user.get("id"),Db.now(),subtotal,tax,subtotal.add(tax),"PLACED",name,phone,address,val(b,"notes"));
   for(Object[] line:lines){Db.exec(c,"UPDATE products SET stock=stock-? WHERE id=?",line[2],line[0]);Db.exec(c,"INSERT INTO order_items(order_id,product_id,name_snapshot,qty,unit_price,tax_rate) VALUES(?,?,?,?,?,?)",id,line[0],line[1],line[2],line[3],line[4]);}return map("order_id",id,"total",subtotal.add(tax));
  }
  if(path.equals("/api/orders")&&method.equals("GET"))return map("orders",orders(c,user));
  if(path.matches("/api/orders/\\d+/(cancel|status)")&&method.equals("POST")){
   String[] parts=path.split("/");int id=Integer.parseInt(parts[3]);String action=parts[4];Map<String,Object> order=Db.row(c,"SELECT * FROM orders WHERE id=?",id);if(order==null)throw new Bad("Order not found.",404);if(!"ADMIN".equals(user.get("role"))&&(!order.get("user_id").equals(user.get("id"))||!action.equals("cancel")))throw new Bad("Access denied.",403);
   if(action.equals("cancel")){if(contains(new String[]{"CANCELLED","DELIVERED"},Db.str(order.get("status"))))throw new Bad("This order cannot be cancelled.");Db.exec(c,"UPDATE orders SET status='CANCELLED' WHERE id=?",id);for(Map<String,Object> line:Db.rows(c,"SELECT product_id,qty FROM order_items WHERE order_id=?",id))Db.exec(c,"UPDATE products SET stock=stock+? WHERE id=?",line.get("qty"),line.get("product_id"));}
   else{String status=req(b,"status",30);if(!contains(orderStatuses,status))throw new Bad("Invalid order status.");if("CANCELLED".equals(order.get("status")))throw new Bad("Cannot update a cancelled order.");Db.exec(c,"UPDATE orders SET status=? WHERE id=?",status,id);}return map("ok",true);
  }
  if(path.equals("/api/shows")&&method.equals("GET"))return map("shows",Db.rows(c,"SELECT sh.*,m.title AS movie_title,m.genre,m.duration_min FROM shows sh JOIN movies m ON sh.movie_id=m.id WHERE sh.active=1 AND m.active=1 ORDER BY sh.show_time"),"movies",Db.rows(c,"SELECT * FROM movies WHERE active=1"));
  if(path.equals("/api/bookings")&&method.equals("GET"))return map("bookings",Db.rows(c,"SELECT b.*,s.show_time,s.screen_no,m.title AS movie_title FROM bookings b JOIN shows s ON b.show_id=s.id JOIN movies m ON s.movie_id=m.id WHERE b.user_id=? ORDER BY b.id DESC",user.get("id")));
  if(path.equals("/api/bookings")&&method.equals("POST")){int show=integer(b.get("show_id"),1,Integer.MAX_VALUE),tickets=integer(b.get("tickets"),1,10);Map<String,Object> s=Db.row(c,"SELECT * FROM shows WHERE id=? AND active=1",show);if(s==null||LocalDateTime.parse(Db.str(s.get("show_time"))).isBefore(LocalDateTime.now()))throw new Bad("This show is no longer available.");if(((Number)s.get("total_seats")).intValue()-((Number)s.get("booked_seats")).intValue()<tickets)throw new Bad("Not enough seats available.");Db.exec(c,"UPDATE shows SET booked_seats=booked_seats+? WHERE id=?",tickets,show);int id=Db.insert(c,"INSERT INTO bookings(user_id,show_id,tickets,total,status,created_at) VALUES(?,?,?,?,?,?)",user.get("id"),show,tickets,money(s.get("price")).multiply(BigDecimal.valueOf(tickets)),"BOOKED",Db.now());return map("booking_id",id);}
  if(path.matches("/api/bookings/\\d+/cancel")&&method.equals("POST")){int id=Integer.parseInt(path.split("/")[3]);Map<String,Object> bk=Db.row(c,"SELECT b.*,s.show_time FROM bookings b JOIN shows s ON b.show_id=s.id WHERE b.id=? AND b.user_id=?",id,user.get("id"));if(bk==null||!"BOOKED".equals(bk.get("status"))||!LocalDateTime.parse(Db.str(bk.get("show_time"))).isAfter(LocalDateTime.now()))throw new Bad("This booking cannot be cancelled.");Db.exec(c,"UPDATE bookings SET status='CANCELLED' WHERE id=?",id);Db.exec(c,"UPDATE shows SET booked_seats=booked_seats-? WHERE id=?",bk.get("tickets"),bk.get("show_id"));return map("ok",true);}
  if(!"ADMIN".equals(user.get("role")))throw new Bad("Administrator access required.",403);
  if(path.equals("/api/admin/overview")&&method.equals("GET"))return map("stores",Db.number(c,"SELECT COUNT(*) FROM shops WHERE active=1"),"products",Db.number(c,"SELECT COUNT(*) FROM products WHERE active=1"),"orders",Db.number(c,"SELECT COUNT(*) FROM orders"),"customers",Db.number(c,"SELECT COUNT(*) FROM users WHERE role='CUSTOMER'"),"low_stock",Db.number(c,"SELECT COUNT(*) FROM products WHERE active=1 AND stock<=5"),"revenue",Db.row(c,"SELECT COALESCE(SUM(total),0) AS amount FROM orders WHERE status!='CANCELLED'").get("amount"));
  if(path.equals("/api/admin/shops")&&method.equals("GET"))return map("shops",Db.rows(c,"SELECT * FROM shops ORDER BY id DESC"));
  if(path.equals("/api/admin/products")&&method.equals("GET"))return map("products",Db.rows(c,"SELECT p.*,s.name AS shop_name FROM products p JOIN shops s ON s.id=p.shop_id ORDER BY p.id DESC"));
  if(path.equals("/api/admin/movies")&&method.equals("GET"))return map("movies",Db.rows(c,"SELECT * FROM movies ORDER BY id DESC"),"shows",Db.rows(c,"SELECT sh.*,m.title AS movie_title FROM shows sh JOIN movies m ON m.id=sh.movie_id ORDER BY sh.id DESC"));
  if(path.equals("/api/admin/settings")&&method.equals("POST")){for(String key:new String[]{"name","tagline","announcement"})if(b.containsKey(key)){String value=req(b,key,150);if(Db.row(c,"SELECT key FROM settings WHERE key=?",key)==null)Db.exec(c,"INSERT INTO settings(key,value) VALUES(?,?)",key,value);else Db.exec(c,"UPDATE settings SET value=? WHERE key=?",value,key);}return map("ok",true);}
  if(path.matches("/api/admin/(shops|products|movies|shows)")&&method.equals("POST")){
   String table=path.substring(path.lastIndexOf('/')+1);Map<String,Object> fields=new LinkedHashMap<>();int id=b.containsKey("id")?integer(b.get("id"),1,Integer.MAX_VALUE):0;
   switch(table){case "shops":{String category=req(b,"category",40);if(!contains(new String[]{"TECH","RESTAURANT","GROCERY","SUPPLEMENT","FASHION","LIFESTYLE","OTHER"},category))throw new Bad("Invalid category.");fields.put("name",req(b,"name",80));fields.put("category",category);fields.put("description",val(b,"description"));fields.put("active",active(b.get("active"))?1:0);break;}
    case "products":{int shop=integer(b.get("shop_id"),1,Integer.MAX_VALUE);if(Db.row(c,"SELECT id FROM shops WHERE id=?",shop)==null)throw new Bad("Store does not exist.");String url=val(b,"image_url").trim();if(!url.isEmpty()&&!url.startsWith("https://"))throw new Bad("Image URL must begin with https://");fields.put("shop_id",shop);fields.put("section",req(b,"section",60));fields.put("name",req(b,"name",100));fields.put("price",money(b.get("price")));fields.put("stock",integer(b.get("stock"),0,1000000));fields.put("description",val(b,"description"));fields.put("image_url",url);fields.put("active",active(b.get("active"))?1:0);break;}
    case "movies":fields.put("title",req(b,"title",100));fields.put("director",val(b,"director"));fields.put("genre",val(b,"genre"));fields.put("duration_min",integer(b.get("duration_min"),1,500));fields.put("active",active(b.get("active"))?1:0);break;
    case "shows":{int movie=integer(b.get("movie_id"),1,Integer.MAX_VALUE);if(Db.row(c,"SELECT id FROM movies WHERE id=?",movie)==null)throw new Bad("Movie does not exist.");String when=req(b,"show_time",40);try{LocalDateTime.parse(when);}catch(Exception ex){throw new Bad("Invalid show date and time.");}int seats=integer(b.get("total_seats"),1,5000);if(id>0){Map<String,Object> old=Db.row(c,"SELECT booked_seats FROM shows WHERE id=?",id);if(old!=null&&seats<((Number)old.get("booked_seats")).intValue())throw new Bad("Total seats cannot be below booked seats.");}fields.put("movie_id",movie);fields.put("screen_no",integer(b.get("screen_no"),1,100));fields.put("show_time",when);fields.put("total_seats",seats);fields.put("price",money(b.get("price")));fields.put("active",active(b.get("active"))?1:0);break;}}
   if(fields.values().stream().anyMatch(v->v instanceof String&&((String)v).length()>500))throw new Bad("Field is too long.");
   if(id>0){if(Db.row(c,"SELECT id FROM "+table+" WHERE id=?",id)==null)throw new Bad("Record not found.",404);List<String> parts=new ArrayList<>();for(String k:fields.keySet())parts.add(k+"=?");List<Object> args=new ArrayList<>(fields.values());args.add(id);Db.exec(c,"UPDATE "+table+" SET "+String.join(",",parts)+" WHERE id=?",args.toArray());}
   else{List<String> qs=new ArrayList<>();for(String k:fields.keySet())qs.add("?");id=Db.insert(c,"INSERT INTO "+table+"("+String.join(",",fields.keySet())+") VALUES("+String.join(",",qs)+")",fields.values().toArray());}return map("ok",true,"id",id);
  }
  throw new Bad("Endpoint not found.",404);
 }
 static void send(HttpExchange e,Object o,int status,String cookie)throws IOException{byte[] bytes=Json.encode(o).getBytes(StandardCharsets.UTF_8);Headers h=e.getResponseHeaders();h.set("Content-Type","application/json; charset=utf-8");h.set("Cache-Control","no-store");h.set("X-Content-Type-Options","nosniff");if(cookie!=null)h.set("Set-Cookie",cookie);e.sendResponseHeaders(status,bytes.length);try(OutputStream out=e.getResponseBody()){out.write(bytes);}}
 static void request(HttpExchange e)throws IOException{String path=e.getRequestURI().getPath(),method=e.getRequestMethod();if(!path.startsWith("/api/")){if(!method.equals("GET")){send(e,map("error","Method not allowed"),405,null);return;}Path base=Path.of("web").toAbsolutePath().normalize();Path file=base.resolve(path.equals("/")?"index.html":path.substring(1)).normalize();if(!file.startsWith(base)||!Files.isRegularFile(file)){file=base.resolve("index.html");}String fn=file.getFileName().toString();String mime=fn.endsWith(".css")?"text/css":fn.endsWith(".js")?"application/javascript":fn.endsWith(".svg")?"image/svg+xml":fn.endsWith(".png")?"image/png":fn.endsWith(".jpg")?"image/jpeg":"text/html";byte[] bytes=Files.readAllBytes(file);e.getResponseHeaders().set("Content-Type",mime+"; charset=utf-8");e.getResponseHeaders().set("X-Content-Type-Options","nosniff");e.sendResponseHeaders(200,bytes.length);try(OutputStream out=e.getResponseBody()){out.write(bytes);}return;}
  if(!method.equals("GET")&&!method.equals("POST")){send(e,map("error","Method not allowed"),405,null);return;}
  if(method.equals("POST")){String origin=e.getRequestHeaders().getFirst("Origin"),host=e.getRequestHeaders().getFirst("Host");if(origin!=null&&!origin.equals("http://"+host)&&!origin.equals("https://"+host)){send(e,map("error","Invalid request origin"),403,null);return;}}
  String token="";List<String> cookieHeaders=e.getRequestHeaders().get("Cookie");if(cookieHeaders!=null)for(String hdr:cookieHeaders)for(String part:hdr.split(";"))if(part.trim().startsWith("striker_session="))token=part.trim().substring(16);
  try{Map<String,Object> body=new LinkedHashMap<>();if(method.equals("POST")){byte[] raw=e.getRequestBody().readNBytes(100001);if(raw.length>100000)throw new Bad("Request too large.",413);Object parsed=Json.parse(raw.length==0?"{}":new String(raw,StandardCharsets.UTF_8));if(!(parsed instanceof Map))throw new Bad("Invalid request data.");body=(Map<String,Object>)parsed;}
   synchronized(dbLock){try(Connection c=Db.connect()){c.setAutoCommit(false);try{Integer uid=sessions.get(token);Map<String,Object> user=uid==null?null:account(c,uid);Object result=handle(c,method,path,body,user);Map<String,Object> m=(Map<String,Object>)result;String setCookie=null;if(m.containsKey("login_user_id")){byte[] t=new byte[48];random.nextBytes(t);String newToken=Base64.getUrlEncoder().withoutPadding().encodeToString(t);sessions.put(newToken,((Number)m.remove("login_user_id")).intValue());setCookie="striker_session="+newToken+"; HttpOnly; SameSite=Strict; Path=/; Max-Age=604800";}else if(Boolean.TRUE.equals(m.get("logout"))){sessions.remove(token);setCookie="striker_session=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0";}c.commit();send(e,m,200,setCookie);}catch(Exception x){c.rollback();throw x;}}}
  }catch(Bad b){send(e,map("error",b.getMessage()),b.code,null);}catch(Exception ex){System.err.println("Request error: "+ex);ex.printStackTrace();send(e,map("error",ex instanceof IllegalArgumentException?"Invalid request data.":"Database or server error. Please try again."),ex instanceof IllegalArgumentException?400:500,null);}
 }
 public static void main(String[] args)throws Exception{Db.initialize();int port=Integer.parseInt(System.getenv().getOrDefault("STRIKER_PORT","8081"));HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",port),0);server.createContext("/",Server::request);server.setExecutor(Executors.newFixedThreadPool(12));Runtime.getRuntime().addShutdownHook(new Thread(Db::checkpoint));server.start();System.out.println("Striker Mall (Java) running at http://localhost:"+port);System.out.println("Press Ctrl+C to stop.");}
}
